-- Starter content for the business "Ideas" tab. DRAFT: approved by ZAYA. Idempotent by sequence number.
insert into public.content_items (id, kind, title, body, sort)
select md5('zaya-idea-' || n)::uuid, kind,
       jsonb_build_object('ru', title, 'uz', '', 'en', ''),
       jsonb_build_object('ru', body, 'uz', '', 'en', ''),
       n
from (values
  (1, 'pr', 'Покажите людей, а не только продукт', 'Бренды, которые снимают реальных людей разного возраста, роста и типажа, вызывают больше доверия. Покажите в кампании тех, кто действительно пользуется вашим продуктом.'),
  (2, 'pr', 'Расскажите историю за кадром', 'Короткий репортаж со съёмки (подготовка, команда, выбор образов) даёт охваты без бюджета на рекламу. Опубликуйте его в Stories и Reels.'),
  (3, 'pr', 'Запустите коллаборацию с локальным автором', 'Сотрудничество с известным в городе фотографом или блогером расширяет аудиторию и добавляет кампании живости.'),
  (4, 'pr', 'Сделайте закрытый показ для клиентов', 'Небольшое событие для постоянных клиентов и партнёров создаёт ощущение причастности и приносит контент для соцсетей.'),
  (5, 'pr', 'Соберите пресс-кит после съёмки', 'Отберите 10 лучших кадров, короткое описание кампании и контакты. С таким набором легче получить публикации в СМИ.'),
  (6, 'pr', 'Опубликуйте итоги кампании', 'Через неделю после запуска покажите результаты: охваты, отзывы, лучшие кадры. Это закрепляет эффект и мотивирует аудиторию вернуться.'),
  (7, 'media', 'Снимайте вертикально и коротко', 'Для Reels, TikTok и Stories лучше работают ролики 15–30 секунд в вертикальном формате с кадром лица в первые две секунды.'),
  (8, 'media', 'Один образ — несколько форматов', 'На одной съёмке получите фото, вертикальное видео и короткий ролик. Это экономит бюджет и обеспечивает единый стиль везде.'),
  (9, 'media', 'Используйте естественный свет', 'Дневной свет у окна или на улице делает кадры живыми и убедительными. Студийная съёмка нужна только для строгого каталога.'),
  (10, 'media', 'Подберите площадки под аудиторию', 'Instagram и TikTok — широкая аудитория и молодёжь, Telegram-каналы — лояльные клиенты, Facebook и YouTube — старшая аудитория и длинные форматы.'),
  (11, 'media', 'Дайте чёткое техническое задание', 'Список кадров, референсы и сроки в брифе сокращают число правок и ускоряют результат. Чем точнее бриф, тем меньше вопросов к команде.'),
  (12, 'motivation', 'Говорим стереотипам нет', 'Красота не имеет единого стандарта. Рост, возраст, телосложение и внешность — это разнообразие, которое делает бренд живым.'),
  (13, 'motivation', 'Работаем без границ', 'Мы отбираем людей за характер и мастерство, а не за шаблонную картинку. Ваш бренд может показать больше, чем принято.'),
  (14, 'motivation', 'Уникальность — это сила', 'Люди доверяют тем, кто выглядит как они сами. Показывайте разные лица, и ваша аудитория увидит себя в вашем бренде.'),
  (15, 'motivation', 'Смело — значит заметно', 'Кампании, которые ломают привычные рамки, запоминаются надолго. Не бойтесь выбрать неожиданного героя вашей истории.'),
  (16, 'motivation', 'Профессионализм важнее шаблона', 'Хорошая модель умеет передать настроение и смысл, а не только красивую форму. Доверьтесь опыту и характеру.'),
  (17, 'motivation', 'Ваша высота начинается здесь', 'Каждый сильный бренд когда-то сделал первый смелый шаг. Сделайте его вместе с ZAYA.')
) as t(n, kind, title, body)
on conflict (id) do nothing;
